effect.shader:
void main() {
    // o alfa da camada manda: "fora = preto" pinta de preto, nao inventa opacidade
    float aOrig = texture(inputImg, acScreenNorm).a;
    vec2 p = (acScreenNorm - 0.5) * 2.0;
    p.x *= acAspect;
    float r = length(p);
    if (r > 1.0) {
        if (black) { fragColor = vec4(0.0, 0.0, 0.0, aOrig); return; }
        else { fragColor = texture(inputImg, acScreenNorm); return; }
    }
    float theta = r * fov;
    vec2 dir = (r > 1e-5) ? p / r : vec2(0.0);
    vec2 q = dir * tan(theta) / zoom;
    q.x /= acAspect;
    q = q * 0.5 + 0.5;
    if (q.x < 0.0 || q.x > 1.0 || q.y < 0.0 || q.y > 1.0) {
        if (black) { fragColor = vec4(0.0, 0.0, 0.0, aOrig); return; }
    }
    fragColor = texture(inputImg, clamp(q, 0.0, 1.0));
}
